    dx = P.axis.x * z + (P.t1.x * cos(phi) + P.t2.x * sin(phi)) * s;
    dy = P.axis.y * z + (P.t1.y * cos(phi) + P.t2.y * sin(phi)) * s;
    dz = P.axis.z * z + (P.t1.z * cos(phi) + P.t2.z * sin(phi)) * s;
